// ===========================================================================
// Фикстура §6.6: лучи и запросы формы.
//
// Геометрия нарочно простая и далеко от границ мира (они тут невидимые и
// нетвёрдые): по ней видно, что именно делает луч — попадает, не попадает,
// начинает внутри, идёт ровно по стыку плит или упирается в выключенную форму.
//
//   ray-box    x 1100..1300, y 350..450  — цель обычного луча;
//   ray-far    x 1480..1520              — стена ЗА ray-box: проверяет, что
//                                          «начал внутри» не гасит луч целиком;
//   shared-a/b стык ровно по x = 2300    — луч по стыку и через общий угол;
//   layer-box  слой 0x4                  — маска запроса решает, видно ли его.
// ===========================================================================

$.ready(() => {
    $.world.gravity(0, 1200).color('#101820')
        .bounds(-2000, -2000, 8000, 8000, { solid: false });

    // Цель: x 1100..1300, y 350..450 (центр 1200, 400).
    $('<wall>', { id: 'ray-box' }).at(1200, 400).size(200, 100).appendTo($.world);

    // Стена за целью: x 1480..1520. Луч, начавшийся внутри ray-box, обязан
    // найти именно её, а не «погаснуть» на собственном перекрытии.
    $('<wall>', { id: 'ray-far' }).at(1500, 400).size(40, 300).appendTo($.world);

    // Две плиты встык: a — x 2100..2300, b — x 2300..2500, общая кромка
    // x = 2300 и общий угол (2300, 350).
    $('<wall>', { id: 'shared-a' }).at(2200, 400).size(200, 100).appendTo($.world);
    $('<wall>', { id: 'shared-b' }).at(2400, 400).size(200, 100).appendTo($.world);

    // Стена на слое 0x4: её видит только запрос с этой маской.
    $('<wall>', { id: 'layer-box' }).at(1200, 700).size(200, 100)
        .layerBits(0x4).appendTo($.world);
});
